window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-0412972a5598f4d6"]={"versions": [{"id": "FIG-0412972a5598f4d6", "releases": ["R3.0.7"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm aus dem Meta-Modell des AUTOSAR-Software-Component-Templates. Das Diagramm spezifiziert die strukturelle Anbindung und Metadaten-Definition von Kalibrierparametern an Schnittstellenanschlüssen (<code>PortPrototype</code>) über Annotationen (<code>CalibrationPortAnnotation</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><code>PortPrototype</code>: Abstrahierter Port eines Software-Components mit Stereotyp <code>«atpPrototype»</code> und Spezialisierung/Herkunft <code>Identifiable</code>. Besitzt per Komposition (<code>+calibrationPortAnnotation</code>, Kardinalität <code>0..*</code>) Annotationen vom Typ <code>CalibrationPortAnnotation</code>.\n</li><li><code>CalibrationPortAnnotation</code>: Spezialisierung von <code>GeneralAnnotation</code>. Repräsentiert Kalibrierparameter-spezifische Metadaten für den übergeordneten Port.\n</li><li><code>CalprmElementPrototype</code>: Spezialisierung von <code>DataPrototype</code>. Wird über die gerichtete Assoziation <code>+calprmElement</code> mit der Multiplizität genau <code>1</code> von <code>CalibrationPortAnnotation</code> referenziert.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Als statisches Meta-Modell-Klassendiagramm definiert die Abbildung keine dynamischen Sequenzen oder Zustandsübergänge zur Laufzeit. Es beschreibt die deklarative Konfigurationsstruktur von Kalibrierannotations-Elementen im XML-/ARXML-Modell.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Für <code>CalibrationPortAnnotation</code> ist eine formale Integritätsbedingung (Constraint) explizit modelliert: <code>{&quot;The corresponding port interface must be a CalprmInterface.&quot;}</code>. Damit darf eine <code>CalibrationPortAnnotation</code> normativ nur an Ports instanziiert werden, deren Schnittstellentyp ein <code>CalprmInterface</code> ist. Jede Instanz verweist zudem verpflichtend auf genau ein <code>CalprmElementPrototype</code>.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-cb841f994312ad8e", "releases": ["R3.1.5"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm aus dem Meta-Modell des AUTOSAR-Software-Component-Templates. Das Diagramm spezifiziert die strukturelle Anbindung und Metadaten-Definition von Kalibrierparametern an Schnittstellenanschlüssen (<code>PortPrototype</code>) über Annotationen (<code>CalibrationPortAnnotation</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><code>PortPrototype</code>: Abstrahierter Port eines Software-Components mit Stereotyp <code>«atpPrototype»</code> und Spezialisierung/Herkunft <code>Identifiable</code>. Besitzt per Komposition (<code>+calibrationPortAnnotation</code>, Kardinalität <code>0..*</code>) Annotationen vom Typ <code>CalibrationPortAnnotation</code>.\n</li><li><code>CalibrationPortAnnotation</code>: Spezialisierung von <code>GeneralAnnotation</code>. Repräsentiert Kalibrierparameter-spezifische Metadaten für den übergeordneten Port.\n</li><li><code>CalprmElementPrototype</code>: Spezialisierung von <code>DataPrototype</code>. Wird über die gerichtete Assoziation <code>+calprmElement</code> mit der Multiplizität genau <code>1</code> von <code>CalibrationPortAnnotation</code> referenziert.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Als statisches Meta-Modell-Klassendiagramm definiert die Abbildung keine dynamischen Sequenzen oder Zustandsübergänge zur Laufzeit. Es beschreibt die deklarative Konfigurationsstruktur von Kalibrierannotations-Elementen im XML-/ARXML-Modell.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Für <code>CalibrationPortAnnotation</code> ist eine formale Integritätsbedingung (Constraint) explizit modelliert: <code>{&quot;The corresponding port interface must be a CalprmInterface.&quot;}</code>. Damit darf eine <code>CalibrationPortAnnotation</code> normativ nur an Ports instanziiert werden, deren Schnittstellentyp ein <code>CalprmInterface</code> ist. Jede Instanz verweist zudem verpflichtend auf genau ein <code>CalprmElementPrototype</code>.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-b3c55618246e862a", "releases": ["R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm aus dem Meta-Modell des AUTOSAR-Software-Component-Templates. Das Diagramm spezifiziert die strukturelle Anbindung und Metadaten-Definition von Kalibrierparametern an Schnittstellenanschlüssen (<code>PortPrototype</code>) über Annotationen (<code>CalibrationPortAnnotation</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><code>PortPrototype</code>: Abstrahierter Port eines Software-Components mit Stereotyp <code>«atpPrototype»</code> und Spezialisierung/Herkunft <code>Identifiable</code>. Besitzt per Komposition (<code>+calibrationPortAnnotation</code>, Kardinalität <code>0..*</code>) Annotationen vom Typ <code>CalibrationPortAnnotation</code>.\n</li><li><code>CalibrationPortAnnotation</code>: Spezialisierung von <code>GeneralAnnotation</code>. Repräsentiert Kalibrierparameter-spezifische Metadaten für den übergeordneten Port.\n</li><li><code>CalprmElementPrototype</code>: Spezialisierung von <code>DataPrototype</code>. Wird über die gerichtete Assoziation <code>+calprmElement</code> mit der Multiplizität genau <code>1</code> von <code>CalibrationPortAnnotation</code> referenziert.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Als statisches Meta-Modell-Klassendiagramm definiert die Abbildung keine dynamischen Sequenzen oder Zustandsübergänge zur Laufzeit. Es beschreibt die deklarative Konfigurationsstruktur von Kalibrierannotations-Elementen im XML-/ARXML-Modell.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Für <code>CalibrationPortAnnotation</code> ist eine formale Integritätsbedingung (Constraint) explizit modelliert: <code>{&quot;The corresponding port interface must be a CalprmInterface.&quot;}</code>. Damit darf eine <code>CalibrationPortAnnotation</code> normativ nur an Ports instanziiert werden, deren Schnittstellentyp ein <code>CalprmInterface</code> ist. Jede Instanz verweist zudem verpflichtend auf genau ein <code>CalprmElementPrototype</code>.</p>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-0412972a5598f4d6", "to": "FIG-cb841f994312ad8e", "fr": "R3.0.7", "tr": "R3.1.5", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-cb841f994312ad8e", "to": "FIG-b3c55618246e862a", "fr": "R3.1.5", "tr": "R3.2.3", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
